// Um item por worker: cada um vira uma execucao independente do workflow Worker
const cfg = $('Config').first().json;
return Array.from({ length: cfg.workers }, (_, i) => ({
  json: { run_id: cfg.run_id, worker: 'W' + (i + 1), calls: cfg.calls },
}));

// Analisa se a fila global respeitou o limite somando TODAS as execucoes
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json)
  .filter((r) => r.run_id === cfg.run_id && r.at_ms)
  .sort((a, b) => a.at_ms - b.at_ms);
const expected = cfg.workers * cfg.calls;
if (!rows.length) {
  return [{ json: { verdict: 'SEM DADOS — confira se o workflow Worker está publicado, a base_url e a credencial do node Tess AI', expected } }];
}
const errors = rows.filter((r) => r.status !== 'ok');
const rateLimited = errors.filter((r) => /rate limit|429/i.test(r.error)).length;
const duration = (rows[rows.length - 1].at_ms - rows[0].at_ms) / 1000;
const rate = rows.length > 1 && duration > 0 ? (rows.length - 1) / duration : 0;
const gaps = rows.slice(1).map((r, i) => r.at_ms - rows[i].at_ms);
// maior numero de chamadas em qualquer janela de 5 s
let maxIn5 = 0;
for (let i = 0, j = 0; i < rows.length; i++) {
  while (rows[i].at_ms - rows[j].at_ms >= 5000) j++;
  maxIn5 = Math.max(maxIn5, i - j + 1);
}
const perWorker = {};
for (const r of rows) perWorker[r.worker] = (perWorker[r.worker] || 0) + 1;
const respected = rateLimited === 0 && rate <= cfg.rps * 1.15 && maxIn5 <= cfg.rps * 5 + 2;
const queueOk = rate <= cfg.rps * 1.15 && maxIn5 <= cfg.rps * 5 + 2;
return [{
  json: {
    verdict: errors.length === rows.length
      ? 'INCONCLUSIVO — todas as chamadas falharam (veja error_samples); o espaçamento ' + (queueOk ? 'respeitou' : 'NÃO respeitou') + ' o limite'
      : respected && errors.length === 0 && rows.length === expected
        ? 'OK — as execuções paralelas respeitaram o limite como uma fila única, sem erros'
        : 'ATENÇÃO — veja os números abaixo',
    run_id: cfg.run_id,
    calls_expected: expected,
    calls_recorded: rows.length,
    ok: rows.length - errors.length,
    errors: errors.length,
    rate_limited_429: rateLimited,
    configured_rps: cfg.rps,
    effective_rate_per_s: Number(rate.toFixed(2)),
    max_calls_in_any_5s: maxIn5,
    duration_s: Number(duration.toFixed(1)),
    min_gap_ms: gaps.length ? Math.min(...gaps) : null,
    avg_gap_ms: gaps.length ? Math.round(gaps.reduce((a, b) => a + b, 0) / gaps.length) : null,
    calls_per_worker: perWorker,
    error_samples: errors.slice(0, 5).map((e) => e.error),
  },
}];
